from math import sqrt

def generate_primes(n):
    """Generate a list of primes up to n."""
    sieve = [True] * (n + 1)
    for x in range(2, int(sqrt(n)) + 1):
        if sieve[x]:
            for i in range(x * x, n + 1, x):
                sieve[i] = False
    return [i for i in range(2, n + 1) if sieve[i]]

def generate_semi_primes(primes):
    """Generate a list of semi-primes up to n."""
    semi_primes = set()
    for i in range(len(primes)):
        for j in range(i, len(primes)):
            semi_primes.add(primes[i] * primes[j])
    return sorted(list(semi_primes))

def solve(N: int) -> str:
    """Determines if the integer N can be expressed as the sum of two semi-primes."""
    primes = generate_primes(100)  # Upper bound for N is 200, primes up to 100 should suffice
    semi_primes = generate_semi_primes(primes)
    for semi_prime in semi_primes:
        if semi_prime > N:
            break
        if (N - semi_prime) in semi_primes:
            return "YES"
    return "NO"

